{
  "设计要点": [
    "核心吸引力不是外卖职业本身，而是配送能力在乱世中改变事件结果：曹操催单成为检验卖点的代表性行动，主角送什么、怎么送、结果如何不同，开篇即见能力价值。",
    "职业是入口而非边界：配送对象从个人到军队，配送内容从食物到军情、人才、物资，配送规模从单点到跨战区，关系从跑腿到被各方需要，责任从完成订单到影响战局。",
    "轻松热血来自主角用现代服务思维解决三国难题，不靠权谋厚黑，而是靠准时、守信、路线规划、客户沟通，让名将和势力因实际受益而改变态度。",
    "情绪回报分三层：单次订单完成的即时爽感、与名将建立信任的关系回报、个人影响力扩大后能参与更大事件的成长回报。",
    "不写后宫不写争霸，主角追求是活下去、把单送好、在乱世建立自己的配送网络和信用，影响力扩大是结果而非目标。"
  ],
  "具体事件": "曹操在兖州整军时急需一批伤药和几封军情信送到前线夏侯惇处，正常路程三日，但军情紧急。陈默接单后利用对地形的熟悉和现代路线规划，避开山匪与泥沼，一日半送达。夏侯惇验货时发现药包外裹着防潮油布，军情信按紧急程度分色标注，随口问陈默能否再送一批箭矢到东线。陈默没有立刻答应，而是先报出路线风险与所需时间，夏侯惇因此认真对待这个送外卖的。",
  "人物选择": "陈默选择先完成曹操的订单，但在交付时主动说明路线风险与时间成本，不卑不亢。理由：他需要建立信用，但不想被当成可随意使唤的小卒。现代外卖员的职业习惯让他习惯先确认需求、评估可行性、再报价，这种专业感反而让夏侯惇和曹操意识到他的价值不止于跑腿。",
  "情绪余韵": "事件结束后不立刻接新危机。陈默在军营外休息，摸到怀里曹操给的赏钱，又看到夏侯惇派人送来的一壶水和半块干饼，意识到自己第一次在乱世不是因为武力或出身被尊重，而是因为把一件事准时做好。他想起现代的外卖评分，笑了一下，把干饼掰开泡水吃。下一段承接他决定在附近找个落脚点，因为夏侯惇说'东线可能还有单'，但没催他。",
  "方法应用": [
    {
      "编号": "法350",
      "如何体现": "用曹操催单这一代表性行动检验核心吸引力：陈默送的不是普通食物，而是伤药与军情信，结果不是简单签收，而是因防潮包装、分色标注、路线规划让夏侯惇主动追加需求，直接展示配送能力改变三国事件。"
    },
    {
      "编号": "法351",
      "如何体现": "从送单对象、规模、关系三个维度展示发展空间：对象从曹操到夏侯惇，规模从单次送药到可能送箭矢到东线，关系从完成订单到被认真对待，让职业成为持续卷入战争的入口而非重复任务。"
    },
    {
      "编号": "参194",
      "如何体现": "开篇兑现看点：陈默在第一次重要订单中就与名将夏侯惇相识，因专业能力被记住，并卷入曹操军的战时需求，建立轻松热血的情绪预期，同时给出即时回报（赏钱、尊重、后续可能）。"
    }
  ],
  "自查": [
    "作者原意：轻松热血、不后宫不争霸、职业是入口，设计未偏离。",
    "事实来源：参考方法仅用于判断卖点与回报，未把参考内容当本书事实。",
    "人物动机：陈默先评估风险再报价，符合现代外卖员习惯，也符合乱世求生逻辑。",
    "因果：曹操催单→陈默送达→夏侯惇认可→追加需求，链条清晰。",
    "期待兑现：开篇即见配送能力改变事件，读者看到名将因专业能力重视主角。",
    "情绪释放：余韵用休息、赏钱、干饼、笑一下完成释放，不拖沓不冲淡。",
    "余韵与承接：余韵后自然承接落脚点和东线可能，不立刻新危机。"
  ]
}

